-- =====================================================
-- 2. CREATE HELPER FUNCTIONS (Non-recursive)
-- =====================================================

-- Safe function to check if user is staff (avoids recursion)
CREATE OR REPLACE FUNCTION auth.is_staff()
RETURNS BOOLEAN AS $
BEGIN
    -- Use auth.jwt() to get role from JWT token instead of querying profiles
    -- This avoids the infinite recursion issue
    RETURN COALESCE(
        (auth.jwt() ->> 'user_metadata' ->> 'role') IN ('admin', 'vet', 'assistant', 'receptionist'),
        false
    );
END;
$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- Safe function to check if user is admin
CREATE OR REPLACE FUNCTION auth.is_admin()
RETURNS BOOLEAN AS $
BEGIN
    RETURN COALESCE(
        (auth.jwt() ->> 'user_metadata' ->> 'role') = 'admin',
        false
    );
END;
$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- Safe function to check if user is client
CREATE OR REPLACE FUNCTION auth.is_client()
RETURNS BOOLEAN AS $
BEGIN
    RETURN COALESCE(
        (auth.jwt() ->> 'user_metadata' ->> 'role') = 'client',
        false
    );
END;
$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- =====================================================
-- 3. PROFILES TABLE POLICIES (Critical - avoid recursion)
-- =====================================================

-- Drop existing problematic policies
DROP POLICY IF EXISTS "Users can view own profile" ON profiles;
DROP POLICY IF EXISTS "Users can update own profile" ON profiles;
DROP POLICY IF EXISTS "Users can insert own profile" ON profiles;
DROP POLICY IF EXISTS "Staff can view all profiles" ON profiles;

-- Create safe, non-recursive policies for profiles
CREATE POLICY "profiles_select_own"
ON profiles FOR SELECT
TO authenticated
USING (auth.uid() = id);

CREATE POLICY "profiles_update_own"
ON profiles FOR UPDATE
TO authenticated
USING (auth.uid() = id);

CREATE POLICY "profiles_insert_own"
ON profiles FOR INSERT
TO authenticated
WITH CHECK (auth.uid() = id);

-- Staff can view all profiles (using JWT-based check)
CREATE POLICY "profiles_select_staff"
ON profiles FOR SELECT
TO authenticated
USING (auth.is_staff());

-- =====================================================
-- 4. CLIENTS TABLE POLICIES
-- =====================================================

-- Drop existing policies
DROP POLICY IF EXISTS "Clients can view own record" ON clients;
DROP POLICY IF EXISTS "Clients can update own record" ON clients;
DROP POLICY IF EXISTS "Staff can manage clients" ON clients;

-- Create new policies
CREATE POLICY "clients_select"
ON clients FOR SELECT
TO authenticated
USING (
    auth.is_staff() OR 
    (user_id = auth.uid())
);

CREATE POLICY "clients_insert"
ON clients FOR INSERT
TO authenticated
WITH CHECK (
    auth.is_staff() OR 
    (user_id = auth.uid())
);

CREATE POLICY "clients_update"
ON clients FOR UPDATE
TO authenticated
USING (
    auth.is_staff() OR 
    (user_id = auth.uid())
);

CREATE POLICY "clients_delete"
ON clients FOR DELETE
TO authenticated
USING (auth.is_staff());

-- =====================================================
-- 5. PATIENTS TABLE POLICIES
-- =====================================================

-- Drop existing policies
DROP POLICY IF EXISTS "Clients can view own pets" ON patients;
DROP POLICY IF EXISTS "Clients can create own pets" ON patients;
DROP POLICY IF EXISTS "Clients can update own pets" ON patients;
DROP POLICY IF EXISTS "Staff can view all pets" ON patients;
DROP POLICY IF EXISTS "Staff can manage all pets" ON patients;

-- Create new policies
CREATE POLICY "patients_select"
ON patients FOR SELECT
TO authenticated
USING (
    auth.is_staff() OR 
    client_id IN (SELECT id FROM clients WHERE user_id = auth.uid())
);

CREATE POLICY "patients_insert"
ON patients FOR INSERT
TO authenticated
WITH CHECK (
    auth.is_staff() OR 
    client_id IN (SELECT id FROM clients WHERE user_id = auth.uid())
);

CREATE POLICY "patients_update"
ON patients FOR UPDATE
TO authenticated
USING (
    auth.is_staff() OR 
    client_id IN (SELECT id FROM clients WHERE user_id = auth.uid())
);

CREATE POLICY "patients_delete"
ON patients FOR DELETE
TO authenticated
USING (auth.is_staff());

-- =====================================================
-- 6. APPOINTMENTS TABLE POLICIES
-- =====================================================

-- Drop existing policies
DROP POLICY IF EXISTS "Clients can view own appointments" ON appointments;
DROP POLICY IF EXISTS "Clients can create own appointments" ON appointments;
DROP POLICY IF EXISTS "Clients can update own appointments" ON appointments;
DROP POLICY IF EXISTS "Staff can view all appointments" ON appointments;
DROP POLICY IF EXISTS "Staff can manage all appointments" ON appointments;

-- Create new policies
CREATE POLICY "appointments_select"
ON appointments FOR SELECT
TO authenticated
USING (
    auth.is_staff() OR 
    client_id IN (SELECT id FROM clients WHERE user_id = auth.uid())
);

CREATE POLICY "appointments_insert"
ON appointments FOR INSERT
TO authenticated
WITH CHECK (
    auth.is_staff() OR 
    client_id IN (SELECT id FROM clients WHERE user_id = auth.uid())
);

CREATE POLICY "appointments_update"
ON appointments FOR UPDATE
TO authenticated
USING (
    auth.is_staff() OR 
    (client_id IN (SELECT id FROM clients WHERE user_id = auth.uid()) AND status IN ('scheduled', 'confirmed'))
);

CREATE POLICY "appointments_delete"
ON appointments FOR DELETE
TO authenticated
USING (auth.is_staff());

