-- =====================================================
-- 12. PUBLIC POLICIES (for landing page)
-- =====================================================

-- Allow public read access to published landing content
CREATE POLICY "landing_content_public_read"
ON landing_content FOR SELECT
TO anon, authenticated
USING (published = true);

CREATE POLICY "landing_sections_public_read"
ON landing_sections FOR SELECT
TO anon, authenticated
USING (
    visible = true AND 
    content_id IN (SELECT id FROM landing_content WHERE published = true)
);

